let disclaimerTimer=null, disclaimerRemainingMs=10000, disclaimerStartedAt=0, disclaimerVisibilityBound=false;
function stopDisclaimerTimer(){if(disclaimerTimer){clearInterval(disclaimerTimer);disclaimerTimer=null}if(disclaimerStartedAt){disclaimerRemainingMs=Math.max(0,disclaimerRemainingMs-(Date.now()-disclaimerStartedAt));disclaimerStartedAt=0}}
function updateDisclaimerStatus(remaining=disclaimerRemainingMs){const status=app.querySelector('[data-disclaimer-countdown]'),ring=app.querySelector('[data-countdown-ring]'),number=app.querySelector('[data-countdown-number]'),timer=app.querySelector('[data-countdown-timer]');if(!status)return;const seconds=Math.max(1,Math.ceil(remaining/1000)),progress=Math.min(1,Math.max(0,1-remaining/10000));const message=document.hidden?'The countdown pauses while the app is in the background.':'Opening the app in '+seconds+' '+(seconds===1?'second':'seconds')+'.';if(status.textContent!==message)status.textContent=message;if(number&&number.textContent!==String(seconds))number.textContent=String(seconds);if(ring)ring.style.strokeDashoffset=String(100-progress*100);if(timer)timer.setAttribute('aria-valuenow',String(Math.ceil(remaining/1000)))}
function startDisclaimerTimer(){if(S.view!=='disclaimer'||disclaimerTimer||document.hidden)return;disclaimerStartedAt=Date.now();updateDisclaimerStatus();disclaimerTimer=setInterval(()=>{const left=Math.max(0,disclaimerRemainingMs-(Date.now()-disclaimerStartedAt));if(left<=0){disclaimerRemainingMs=0;stopDisclaimerTimer();S.view='home';render();return}updateDisclaimerStatus(left)},200)}
function dismissDisclaimer(permanent=false){stopDisclaimerTimer();if(permanent)store.set('disclaimerNeverShow',true);S.view='home';render()}
function bindDisclaimerActions(){if(S.view!=='disclaimer'){stopDisclaimerTimer();return}if(disclaimerRemainingMs<=0)disclaimerRemainingMs=10000;if(!disclaimerVisibilityBound){document.addEventListener('visibilitychange',()=>{if(S.view!=='disclaimer')return;if(document.hidden){stopDisclaimerTimer();updateDisclaimerStatus()}else startDisclaimerTimer()});disclaimerVisibilityBound=true}app.querySelector('[data-never-disclaimer]')?.addEventListener('click',()=>dismissDisclaimer(true));updateDisclaimerStatus();startDisclaimerTimer()}
