  return '<section class="card session-suggestion-board"><div class="section-head session-suggestion-head"><div><div class="eyebrow">Live choir session</div><h2 class="serif">Song suggestions</h2><p class="subtle">Members suggest hymns and each person gets one vote. The leader makes the final pick.</p></div><span class="pill-num">'+suggestions.length+'</span></div>'+pickedHtml+historyHtml+nextRound+(!leader?(active?'<button type="button" class="btn soft session-suggest-open" data-open-session-song-picker>'+icon('plus')+' Suggest a song</button>':'<p class="subtle session-suggest-hint">Connect to a live session to suggest and vote on hymns.</p>'):'')+(rows?'<div class="session-suggestion-list">'+rows+'</div>':'<p class="subtle session-suggestions-empty">'+(active?'No songs suggested yet. Be the first to suggest a hymn.':'Start a session to collect song suggestions and votes.')+'</p>')+'</section>';
