  const query=String(S.sessionSongQuery||'').trim().toLowerCase(),results=hymns.filter(song=>!query||(String(song.title||'')+' '+String(song.hymnNumber||'')+' '+String(song.tocTitle||'')).toLowerCase().includes(query)).slice(0,30);
