function connectSessionInvite(rawValue){
  try{
    const invite=JSON.parse(rawValue);
    if(!invite||invite.app!=='sing-in-praise'||invite.type!=='choir-session'||invite.version!==1)throw new Error('wrong invite');
    const host=String(invite.host||''),parts=host.split('.').map(Number);
    const privateIp=parts.length===4&&parts.every(n=>Number.isInteger(n)&&n>=0&&n<=255)&&(parts[0]===10||parts[0]===192&&parts[1]===168||parts[0]===172&&parts[1]>=16&&parts[1]<=31);
    if(!privateIp)throw new Error('not a local invite');
    connectSession(host,invite.port,app.querySelector('[data-session-name-inline]')?.value.trim()||store.get('name','Choir member'));
  }catch{S.sessionError='That code is not a choir session invite. Ask the leader to open Choir Session and show the QR code.';render()}
}
function shareCurrentHymn(){const h=hymn(S.hymn);if(!h){toast('Open a hymn first, then share it with the session.');return}if(S.role!=='leader'||!S.sessionStarted||!window.ChoirNative||typeof window.ChoirNative.broadcastSessionMessage!=='function'){toast('Start a Wi-Fi session as the leader before sharing a hymn.');return}window.ChoirNative.broadcastSessionMessage(JSON.stringify({type:'hymn',hymnId:h.id,title:h.title,by:store.get('name','Choir leader')}));toast('Shared “'+h.title+'” with connected members.')}
