function pick(partId){
  let m=document.createElement('div');m.className='modal-backdrop';
  const pl0=plans().find(x=>x.id===S.plan)||plans()[0],pt0=pl0?pl0.parts.find(x=>x.id===partId):null;
  let pcat=pickCatFor(pt0&&pt0.label);
  const catOpts=()=>catsPresent().map(c=>'<option value="'+esc(c)+'"'+(pcat===c?' selected':'')+'>'+(c==='All'?'All song categories':esc(categoryLabel(c)))+'</option>').join('');
  const available=()=>tocHymns(pcat);
  const label=()=>pcat==='All'?'all song categories':categoryLabel(pcat);
  const matchFn=(h,q)=>{q=String(q||'').toLowerCase();return (h.title+' '+(h.tocTitle||'')+' '+h.hymnNumber+' '+(h.bookNumber||'')+' '+(h.lyrics||'')).toLowerCase().includes(q)};
  const draw=q=>{let list=available().filter(h=>matchFn(h,q)).slice(0,45);let r=m.querySelector('[data-pick-results]');if(r)r.innerHTML=list.map(row).join('');let n=m.querySelector('[data-suggestion-note]');if(n)n.innerHTML='Suggested from <strong>'+esc(label())+'</strong> · '+available().length+' songs available';};
  m.innerHTML='<div class="modal"><div class="modal-head"><div><div class="eyebrow">Mass part'+(pt0&&pt0.label?' · '+esc(pt0.label):'')+'</div><h2>Choose a hymn</h2></div><button class="btn icon" data-close aria-label="Close">'+icon('x')+'</button></div><div class="search"><span class="s-icon">'+icon('search')+'</span><input autofocus placeholder="Search this slot..." data-pick-search></div><div class="field" style="margin-top:10px"><label>Song section</label><select data-pick-cat>'+catOpts()+'</select></div><div class="suggestion-note" data-suggestion-note>Suggested from <strong>'+esc(label())+'</strong> · '+available().length+' songs available</div><div data-pick-results style="margin-top:12px">'+available().slice(0,45).map(row).join('')+'</div></div>';
  document.body.appendChild(m);m.querySelector('[data-close]').onclick=()=>m.remove();m.addEventListener('mousedown',e=>{if(e.target===m)m.remove()});
  m.querySelector('[data-pick-search]').oninput=e=>draw(e.target.value);
  m.querySelector('[data-pick-cat]').onchange=e=>{pcat=e.target.value;draw(m.querySelector('[data-pick-search]').value)};
  m.onclick=e=>{const fav=e.target.closest('[data-fav]');if(fav){e.stopPropagation();const id2=fav.dataset.fav,f=favs(),on=f.includes(id2);store.set('favorites',on?f.filter(x=>x!==id2):f.concat(id2));fav.classList.toggle('on',!on);fav.innerHTML=starSvg(!on);return}let r=e.target.closest('[data-open]');if(r){let ps=plans(),p=ps.find(x=>x.id===S.plan)||plans()[0],part=p.parts.find(x=>x.id===partId);part.hymn=r.dataset.open;part.state='SELECTED';store.set('plans',ps);m.remove();render()}};
}
function step(n){S.slideDir=n>=0?'next':'prev';if(S.ctx?.kind==='mass'){const next=S.ctx.index+n;if(next<0||next>=S.ctx.queue.length){S.slideDir=null;return}S.ctx={...S.ctx,index:next};S.hymn=S.ctx.queue[next].hymnId;store.set('recent',[S.hymn,...recent().filter(x=>x!==S.hymn)].slice(0,30));render();return}if(S.ctx){let pl=plans().find(x=>x.id===S.ctx.planId);if(pl){let q=planQueue(S.ctx.planId);if(q.includes(S.hymn)){let ix=(q.indexOf(S.hymn)+n+q.length)%q.length;openH(q[ix],S.ctx.planId);return}}}let i=hymns.findIndex(x=>x.id===S.hymn);if(i<0||!hymns.length){S.slideDir=null;if(hymns.length)openH(hymns[0].id);return}openH(hymns[(i+n+hymns.length)%hymns.length].id)}
applyTheme(store.get('theme','blue'));
